def transform(grid):
    h,w=len(grid),len(grid[0])
    from collections import Counter, deque
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    out=[row[:] for row in grid]
    if grid[0][0]!=bg:
        # Find a corner containing the background.
        seeds=[(r,c) for r,c in [(0,0),(0,w-1),(h-1,0),(h-1,w-1)] if grid[r][c]==bg]
        if not seeds: return out
        start=seeds[0]
    else: start=(0,0)
    seen={start}; q=deque([start])
    while q:
        r,c=q.popleft()
        for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0<=nr<h and 0<=nc<w and grid[nr][nc]==bg and (nr,nc) not in seen:
                seen.add((nr,nc));q.append((nr,nc))
    for r in range(h):
        for c in range(w):
            if grid[r][c]==bg and (r,c) not in seen:
                out[r][c]=4
    return out
